window.ScripturaLexicons.BDAG_PART_0059 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:" <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-beta-bdag\" data-source=\"BDAG\" data-search=\"β´ béta sinal numérico dois; segundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">β´</td><td>sinal numérico</td><td>dois; segundo</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baal-bdag\" data-source=\"BDAG\" data-search=\"Βάαλ, ὁ Báal nome próprio masculino indeclinável Baal; divindade semítica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Βάαλ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Baal; divindade semítica</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-babylon-bdag\" data-source=\"BDAG\" data-search=\"Βαβυλών, ῶνος, ἡ Babylṓn nome próprio geográfico feminino Babilônia; cidade e potência inimiga de Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Βαβυλών, ῶνος, ἡ</td><td>nome próprio geográfico feminino</td><td>Babilônia; cidade e potência inimiga de Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-badizo-bdag\" data-source=\"BDAG\" data-search=\"βαδίζω badízō verbo andar; caminhar; proceder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαδίζω</td><td>verbo</td><td>andar; caminhar; proceder</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bados-bdag\" data-source=\"BDAG\" data-search=\"βάδος, ὁ bádos substantivo masculino; variante remissiva ver βάτος, ὁ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάδος, ὁ</td><td>substantivo masculino; variante remissiva</td><td>ver βάτος, ὁ</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-batheos-bdag\" data-source=\"BDAG\" data-search=\"βαθέως bathéōs advérbio; forma remissiva ver βαθύς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαθέως</td><td>advérbio; forma remissiva</td><td>ver βαθύς</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bathmos-bdag\" data-source=\"BDAG\" data-search=\"βαθμός, οῦ, ὁ bathmós substantivo masculino degrau; estágio; posição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαθμός, οῦ, ὁ</td><td>substantivo masculino</td><td>degrau; estágio; posição</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bathos-bdag\" data-source=\"BDAG\" data-search=\"βάθος, ους, τό báthos substantivo neutro profundidade física; profundidade figurada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάθος, ους, τό</td><td>substantivo neutro</td><td>profundidade física; profundidade figurada</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bathyno-bdag\" data-source=\"BDAG\" data-search=\"βαθύνω bathýnō verbo aprofundar; cavar fundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαθύνω</td><td>verbo</td><td>aprofundar; cavar fundo</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bathys-bdag\" data-source=\"BDAG\" data-search=\"βαθύς, εῖα, ύ bathýs adjetivo profundo; intenso; muito cedo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαθύς, εῖα, ύ</td><td>adjetivo</td><td>profundo; intenso; muito cedo</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baion-bdag\" data-source=\"BDAG\" data-search=\"βαί̈ον, ου, τό baḯon substantivo neutro ramo de palmeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαί̈ον, ου, τό</td><td>substantivo neutro</td><td>ramo de palmeira</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-balaam-bdag\" data-source=\"BDAG\" data-search=\"Βαλαάμ, ὁ Balaám nome próprio masculino indeclinável Balaão; vidente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Βαλαάμ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Balaão; vidente</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-balak-bdag\" data-source=\"BDAG\" data-search=\"Βαλάκ, ὁ Balák nome próprio masculino indeclinável Balaque; rei moabita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Βαλάκ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Balaque; rei moabita</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-balaneion-bdag\" data-source=\"BDAG\" data-search=\"βαλανεῖον, ου, τό balaneîon substantivo neutro banho público; balneário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαλανεῖον, ου, τό</td><td>substantivo neutro</td><td>banho público; balneário</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ballantion-bdag\" data-source=\"BDAG\" data-search=\"βαλλάντιον, ου, τό ballántion substantivo neutro bolsa de dinheiro; algibeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαλλάντιον, ου, τό</td><td>substantivo neutro</td><td>bolsa de dinheiro; algibeira</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ballo-bdag\" data-source=\"BDAG\" data-search=\"βάλλω bállō verbo lançar; atirar; colocar; depositar; precipitar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάλλω</td><td>verbo</td><td>lançar; atirar; colocar; depositar; precipitar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-banausos-bdag\" data-source=\"BDAG\" data-search=\"βάναυσος, ον bánausos adjetivo vulgar; grosseiro; indigno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάναυσος, ον</td><td>adjetivo</td><td>vulgar; grosseiro; indigno</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baptizo-bdag\" data-source=\"BDAG\" data-search=\"βαπτίζω baptízō verbo lavar ritualmente; mergulhar; batizar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαπτίζω</td><td>verbo</td><td>lavar ritualmente; mergulhar; batizar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baptisma-bdag\" data-source=\"BDAG\" data-search=\"βάπτισμα, ατος, τό báptisma substantivo neutro batismo; rito com água; experiência extraordinária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάπτισμα, ατος, τό</td><td>substantivo neutro</td><td>batismo; rito com água; experiência extraordinária</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baptismos-bdag\" data-source=\"BDAG\" data-search=\"βαπτισμός, οῦ, ὁ baptismós substantivo masculino lavagem ritual; batismo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαπτισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>lavagem ritual; batismo</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:" <article id=\"entry-beta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">β´</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦béta⟧</span><span class=\"separator\">·</span><span>sinal numérico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Sinal numérico: 2</strong> (δύο; Josefo, C. Ap. 1, 157; Ar. [Milne 76, 28]), Hs 8, 9, 1 (códice A em lugar de δύο); Lc 10:35, P⁷⁵ (β̄). Ou <strong>segundo</strong> (δευτέρα), subentendendo-se ἐπιστολή, «epístola» (nos títulos de 2Co, 2Ts, 2Tm, 2Pe, 2Jo, 2Cl, e nas subscrições de 2Ts, 2Tm e 2Jo), ou ὅρασις, «visão» (no título de Hv 2), ou ἐντολή, «mandamento» (no título de Hm 2).</p></section></article> <article id=\"entry-baal-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βάαλ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Báal⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (hebraico בַּעַל, «senhor»; Josefo, Ant. 9, 135s.; 138: ὁ Βάαλ). <strong>Baal</strong>, divindade geralmente adorada pelos semitas, à qual se opuseram vigorosamente Elias e os profetas hebreus posteriores; κάμπτειν γόνυ τῇ Β., «dobrar o joelho diante de Baal», Rm 11:4 (1Rs 19:18: τῷ Β.). O artigo feminino (2Rs 21:3; Jr 2:8; 12:16 e outros; AscIs 2:12; Justino, D. 136, 3) talvez se deva ao costume hebraico de substituir os nomes de divindades estrangeiras por αἰσχύνη, «vergonha» (בּשֶׁת); ver A. Dillmann, Mon.-Ber. d. Berl. Akad. 1881, 601–20; RAC I 1063–1113; W-S §10, 6; B-D-F §53, 4; Mlt-H. 152; Robinson 254. — M-M.</p></section></article> <article id=\"entry-babylon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βαβυλών, ῶνος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Babylṓn⟧</span><span class=\"separator\">·</span><span>nome próprio geográfico feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Alceu Lírico [séculos VII/VI a.C.] 82, 10 D. [48, 10 L-P.]; Ésquilo, Pers. 52 e outros; Septuaginta; ParJer; Fílon; Josefo; SibOr; TestSol 26:6 B; Justino; hebraico בָּבֶל, Gn 11:9; babilônico <em>Bâb-îlu</em> ou <em>Bâbili</em>, interpretado pelos próprios babilônios, por etimologia popular, como «porta dos deuses».) <strong>Babilônia</strong>, capital da Babilônia (Diodoro Sículo 19, 100, 7: Βαβυλῶνα τὴν πόλιν); também designa o país (Bar 1:1, 4, 9, 11 e outros; 1Esd 1:53; 2:11; 4:44 e outros); daí μετοικεσία Βαβυλῶνος, «deportação para a Babilônia» (B-D-F §166), Mt 1:11s., 17; compare At 7:43 (e Pseudo-Calístenes 3, 33, 15: ἐπάνω τῆς Βαβυλωνίας). — Entre os israelitas, Roma passou a receber o nome e numerosas características de Babilônia, como potência mundial hostil a Deus, denunciada pelos profetas (SyrBar 67, 7; SibOr 5, 143; 159; Billerbeck III, 816). Assim também 1Pe 5:13 (ver a variante Ῥώμῃ e C. Hunzinger, em H. Hertzberg Festschrift, 1965, 67–77 [Babilônia, Roma e 1Pedro]). Outros, inclusive G. Manley, EvQ 16, 1944, 138–46, e R. Altheim-Stiehl, Christentum am Roten Meer II, 1973, 298, sustentam, com menor probabilidade, tratar-se da Babilônia egípcia (Diodoro Sículo 1, 56, 3; Estrabão 17, 1, 30; Josefo, Ant. 2, 315). Outros propõem a cidade da Mesopotâmia, mas no tempo de Diodoro Sículo [2, 9, 9], século I a.C., ela se encontrava quase inteiramente desabitada. A associação com Roma é a preferida pela maioria para o Apocalipse (contra: G. A. van den Bergh van Eysinga, NThT 16, 1927, 33ss.; J. Oman, Book of Rv, 1923, 29 e outros; J. Sickenberger, BZ 17, 1926, 270–82; Lohmeyer), onde Babilônia é sempre denominada <em>a Grande</em> (compare Dn 4:30; Josefo, Ant. 8, 153; Alceu, loc. cit., escreveu Βαβύλωνος ἵρας, «Babilônia sagrada»), Ap 16:19; 17:5; 18:10, 21; ἔπεσεν, ἔπεσεν Β., «caiu, caiu Babilônia», 14:8; 18:2 (compare Is 21:9; Jr 28:8). — RAC I 1118–34; M-M; TW.</p></section></article> <article id=\"entry-badizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαδίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦badízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro βαδιοῦμαι; primeiro aoristo ἐβάδισα, Septuaginta (Estesícoro, talvez POxy 2360 I, 4, ver nota editorial sobre o texto fragmentário, e outros, mas raro em poesia). <strong>Andar, caminhar</strong> (nesse sentido desde Hipócrates, Int. 7, p. 274; Aristófanes, Thesm. 617; Xenofonte e posteriores). Figuradamente, acerca da conduta humana (Galeno, CMG V 4, 1, 1, p. 23, 12: β. ἐπὶ σωφροσύνην δι’ ἐγκρατείας; Proverb. Aesopi 121 P.: β. τῶν νόμων ἐνώπιον; SibOr Fgm. 1, 23; Pselo, p. 213, 26), como com περιπατεῖν, πορεύεσθαι e πολιτεύεσθαι: β. κατὰ τὰς ἐπιθυμίας, «proceder segundo os desejos», 1Cl 3:4. — DELG, s.v. βαίνω, p. 157; M-M.</p></section></article> <article id=\"entry-bados-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάδος, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bádos⟧</span><span class=\"separator\">·</span><span>substantivo masculino; variante remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Lc 16:6, variante de leitura; ver βάτος, ὁ.</p></section></article> <article id=\"entry-batheos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαθέως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bathéōs⟧</span><span class=\"separator\">·</span><span>advérbio; forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver βαθύς, final do verbete.</p></section></article> <article id=\"entry-bathmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαθμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bathmós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βαίνω; em diversos sentidos em Estrabão, Luciano e outros; Septuaginta; inscrições; papiros; 4Esd; Pseudo-Sófocles; Fílon; Josefo.)<br/><strong>1. Apoio estruturado para o pé, assinalando uma etapa na subida ou descida: degrau</strong> (compare βαίνω, «dar um passo, andar»; Sófocles; escritores helenísticos [Nägeli 26]; Septuaginta; ApcEsdr 4:8, p. 28, 7 Tdf. e outros; Josefo, Bell. 5, 206; Ant. 8, 140, em sentido físico); ἐπὶ τρίτου βαθμοῦ τοῦ θυσιαστηρίου, «sobre o terceiro degrau do altar», GJs 7:3; compare At 12:10, códice D.<br/><strong>2. Etapa no progresso intelectual ou espiritual: grau, posição, categoria</strong> (Dião Crisóstomo 24 [41], 6; Fílon, Aet. M. 58; Josefo, Bell. 4, 171: οἱ τῶν τολμημάτων βαθμοί, «os graus das ações ousadas»; compare IG XII/2, 243, 16: τοῖς τᾶς ἀξίας βασμοῖς ἀνελόγησε, «manteve-se à altura dos graus de sua dignidade»). β. ἑαυτῷ καλὸν περιποιεῖσθαι, «conquistar para si boa posição (ou categoria)», 1Tm 3:13. Talvez haja, nessa última referência, um termo técnico dos mistérios (um «degrau» na viagem da alma aos céus); compare Herm. Wr. 13, 9: ὁ βαθμὸς οὗτος, ὦ τέκνον, δικαιοσύνης ἐστὶν ἕδρασμα. Além disso, a filosofia parece ter utilizado β. para denotar a aquisição gradual da sabedoria (ver O. Immisch, Philol., nova série 17, 1904, 33, 1). — Sobre a forma da palavra, ver R. Schöll, SBBayAk 1893 II, 500; DELG, s.v. βαίνω, p. 157; M-M.</p></section></article> <article id=\"entry-bathos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάθος, ους, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦báthos⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βαθύς; Ésquilo, Heródoto e posteriores.) Em geral, distância abaixo de alguma coisa.<br/><strong>1. Espaço ou distância abaixo de uma superfície: profundidade</strong> (com ὕψος, Is 7:11; Herm. Wr. 11, 20b), Dg 7:2; com outras dimensões (Aristóteles, Phys. 4, 1, 209a, 5; Dião Crisóstomo 76 [26], 6; Plutarco, Mor. 937f; SIG 973, 6ss.: μῆκος, πλάτος, β., de uma vala; Fílon, Decal. 25; Josefo, Ant. 1, 77), Ef 3:18 (compare a fórmula mágica γενέσθω φῶς πλάτος βάθος μῆκος ὕψος αὐγή, PGM 4, 970s. e 978s.; 12, 157; ver Straub 56). Do solo, Mt 13:5; Mc 4:5 (Josefo, Ant. 8, 63: τῆς γῆς β.; Teofrasto, HP 6, 5, 4: χώρας βάθος; BGU 1122, 16, de plantas: ἔχον τὸ καθῆκον β.). Das profundezas do mar, B 10:10 (compare escólios a Apolônio de Rodes 1, 461; 4, 865s.; Sl 68:3; Am 9:3; Mq 7:19 e outros, Septuaginta). De água profunda, Lc 5:4. Dos olhos fundos por inchaço, Papias 3:2. ὕψωμα οὔτε βάθος, «nem altura nem profundidade», Rm 8:39: como ambos são ditos criaturas e o contexto aparentemente se refere apenas a forças transcendentes, provavelmente designam espíritos astrais; ambos são termos técnicos astronômicos, e β. significa o espaço celeste abaixo do horizonte, de onde surgem os astros (PGM 4, 575: ἀστὴρ ἐκ τ. βάθους ἀναλάμπων).<br/><strong>2. Algo não físico percebido como tão remoto que é difícil avaliá-lo: profundidade figurada</strong> (Ésquilo e outros); ἡ κατὰ βάθους πτωχεία αὐτῶν, «a pobreza deles que desce às profundezas» (Estrabão 9, 3, 5: ἄντρον κοῖλον κατὰ βάθους), isto é, «pobreza extrema», 2Co 8:2; β. πλούτου, «profundidade (isto é, inesgotabilidade) da riqueza» (Sófocles, Aj. 130; compare Josefo, Ant. 1, 271: τὸ τῆς τριχὸς βάθος; Pv 18:3; Eliano, VH 3, 18: πλοῦτος βαθύς; Norden, Agn. Th. 243, 3), Rm 11:33; τὰ β. τῆς θείας γνώσεως, «as profundezas do conhecimento divino», 1Cl 40:1 (Fílon, Poster. Cai. 130: β. τῆς ἐπιστήμης); τὰ β. τοῦ θεοῦ, «as profundezas de Deus», 1Co 2:10 (TestJob 37:6: τοῦ κυρίου); τὰ βάθη τοῦ σατανᾶ, «as profundezas de Satanás», Ap 2:24, variante de leitura (compare Jt 8:14: βάθος καρδίας ἀνθρώπου; τὰ βάθη τῆς καρδίας καὶ τοῦ νοῦ, Justino, D. 121, 2; Eunápio, Vi. Soph. 23, 3, 8, p. 113: β. τῆς ψυχῆς; com κακῶν, Ésquilo, Pers. 465). — DELG, s.v. βαθύς; M-M; TW; Spicq.</p></section></article> <article id=\"entry-bathyno-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαθύνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bathýnō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo ἐβάθυνα, Septuaginta; passivo, terceira pessoa plural ἐβαθύνθησαν, Sl 91:6 (Homero e outros; Septuaginta; Josefo, Bell. 1, 405). <strong>Tornar profundo</strong> (Josefo, Bell. 5, 130); também intransitivo: <strong>ir fundo, penetrar em profundidade</strong> (Proclo, In Rem Publ. II, p. 347, 2 Kroll; Fílon, Poster. Cai. 118: ὁ τῆς διανοίας ὀφθαλμὸς εἴσω προελθὼν καὶ βαθύνας τὰ ἐν αὐτοῖς σπλάγχνοις ἐγκεκρυμμένα κατεῖδε); ἔσκαψεν καὶ ἐβάθυνεν, «cavou e aprofundou, cavou fundo», Lc 6:48. — DELG, s.v. βαθύς; M-M.</p></section></article> <article id=\"entry-bathys-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαθύς, εῖα, ύ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bathýs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βάθος; Homero e outros; inscrições; papiros; Septuaginta; TestJud 7:3; Ath.)<br/><strong>1. Relativo à distância abaixo de uma superfície: profundo</strong> (En 24:2; EpArist 118; Josefo, Ant. 10, 170), de um poço (Pitágoras, Ep. 3, 3; Cáriton 8, 1, 10: φρέαρ β.), Jo 4:11.<br/><strong>2. Relativo a algo não físico percebido como tão remoto que é difícil avaliá-lo: profundo</strong>; τὰ βαθέα τοῦ σατανᾶ, «as profundezas [ocultas] de Satanás», Ap 2:24 (compare Dn 2:22 e ver βάθος 2).<br/><strong>3. Relativo a um ponto extremo numa escala de extensão.</strong> <strong>a. Profundo, intenso</strong>, de sono (Teócrito 8, 65; Luciano e outros; Josefo, Ant. 5, 148; Sir 22:9; 3Mc 5:12; Ath. 12, 2), At 20:9; AcPl Ha 3, 25s.: οἱ δὲ φύλακ̣ε̣[ς βα]θεῖ ὕπνῳ; da paz (Luciano, Tox. 36; Herodiano 4, 10, 1; 7, 9, 5; 4Mc 3:20; Fílon, Somn. 2, 229; SibOr 12, 87; Ath. 1:3), 1Cl 2:2. <strong>b. No extremo de uma escala: muito, extremamente</strong>; ὄρθρου βαθέως (Aristófanes, Vesp. 216; Platão, Crito 43a, Prot. 310a: ἔτι βαθέος ὄρθρου; Flégon, 257 Fgm. 36, 1, 9, p. 1171, 4 Jac.; Fílon, Mut. Nom. 162; Mos. 1, 179; Spec. Leg. 1, 276; PLips 40 II, 10), «bem cedo de manhã», Lc 24:1 (β. [variante βαθέος] deve ser entendido não como advérbio, mas como genitivo de βαθύς, assim como πραέως [πραέος], 1Pe 3:4; compare W-S §9, 5; Robinson 495; B-D-F §46, 3). — DELG; M-M.</p></section></article> <article id=\"entry-baion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαί̈ον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦baḯon⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Vocábulo egípcio, copta «bai»; P. Katz, TLZ 82, 1957, 112; 83, 1958, 316, e B-D-F §6 preferem os acentos βάϊον e βάϊς.) <strong>Ramo de palmeira</strong> (1Mc 13:51; SSol 7:8, Símaco; PFlor 37, 3; C. Wessely, Stud. z. Paläogr. u. Pap.-kunde 22, 1922, n.º 157 [século II d.C.]; compare PTebt II, p. 69. Os papiros preferem a forma βαί̈ς [como N., mas ver B-D-F §6], encontrada também em Querêmon de Alexandria, em Porfírio, Abst. 4, 7; empréstimo na literatura rabínica). τὰ β. τῶν φοινίκων, «os ramos das palmeiras», Jo 12:13 (onde τῶν φ. é, a rigor, redundante; mas compare TestNapht 5:4: βαί̈α φοινίκων; PLeid 13, 6, 7 [século I d.C.]: βαί̈α φοινί[κων]). — W. Farmer, JTS 3, 1952, 62–66; DELG, s.v. βαί̈ς; M-M.</p></section></article> <article id=\"entry-balaam-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βαλαάμ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Balaám⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (hebraico בִּלְעָם). <strong>Balaão</strong>, vidente (Nm 22–24; 31:16; Dt 23:5s.; Js 13:22; 24:9; Mq 6:5; Fílon, Mos. 1, 264ss.; Migr. Abr. 113–15; Josefo, Ant. [Βάλαμος, ου] 4, 104; 107–9; 111; 126; 157; Pirqe Aboth 5, 19). Apresentado como exemplo típico de enganador e falso profeta, Ap 2:14; Jd 11 (βαλαακ no P⁷²); 2Pe 2:15. — RAC II 362–73.</p></section></article> <article id=\"entry-balak-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βαλάκ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Balák⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (hebraico בָּלָק; Septuaginta; Fílon, Conf. Ling. 65; em Josefo, βάλακος, ου [Ant. 4, 107]). <strong>Balaque</strong>, rei moabita (Nm 22:2ss.; 23:7; 24:10; Js 24:9; Mq 6:5), relacionado com Balaão (ver o verbete anterior), Ap 2:14. — Βαλαάκ, em Jd 11, P⁷², em lugar de Βαλαάμ, que se deve consultar.</p></section></article> <article id=\"entry-balaneion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαλανεῖον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦balaneîon⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Aristófanes e outros; inscrições; papiros; TestSol; Justino, D. 13; empréstimo na literatura rabínica.) <strong>Edifício destinado ao banho e à convivência social; banho público, balneário</strong>, MPol 13:1. — F. Yegül, Baths and Bathing in Classical Antiquity, 1992; DELG, s.v. βαλανεύς.</p></section></article> <article id=\"entry-ballantion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαλλάντιον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ballántion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Também βαλάντιον; ver B-D-F §11, 2; Robinson 213; W-S §5, 26a, nota 51; Helbing 15s. Encontrado desde Pseudo-Simônides 157 Diehl²; Epicarmo [século V a.C.], fragmento 10, p. 95: Com. Gr. Fgm. I/1, 1899, Kaibel; O. Bodl 348 recto, 10 [século I a.C.]; PSI 1128, 26 [século III d.C.]; Ateneu 3, 98, num jogo de palavras com βάλλω; Fílon, De Jos. 180 e 207; Septuaginta.) <strong>Bolsa de dinheiro, bolsa, algibeira</strong> (Plutarco, Mor. 62b; 802d; Herodiano 5, 4, 3: βαλλάντια χρημάτων μεστά), Lc 10:4; 12:33; 22:35s. — B. 776; DELG; TW.</p></section></article> <article id=\"entry-ballo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bállō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro βαλῶ; segundo aoristo ἔβαλον, terceira pessoa plural ἔβαλον em Lc 23:34 (Sl 21:19) e At 16:23, mas ἔβαλαν em At 16:37 (B-D-F §81, 3; Mlt-H. 208); perfeito βέβληκα (sobre essa forma, ver bibliografia em LfgrE, s.v. βάλλω, col. 25). Passivo: futuro primeiro βληθήσομαι; aoristo primeiro ἐβλήθην; perfeito βέβλημαι; mais-que-perfeito ἐβεβλήμην (Homero e posteriores). Em geral, pôr algo em movimento por meio de lançamento, desde Homero tanto com sugestão de força quanto em sentido mais suave; opõe-se a ἁμαρτάνω, «errar o alvo».<br/><strong>1. Fazer mover-se de um lugar para outro por movimento vigoroso: lançar, atirar.</strong> <strong>a. Com objeto simples:</strong> espalhar sementes no solo (Diodoro Sículo 1, 36, 4; Sl 125:6, variante de leitura [A. Rahlfs, Psalmi cum Odis, 1931]), Mc 4:26; 1Cl 24:5; AcPlCor 2:26; em comparação, do corpo, τὸ σῶμα … βληθέν, versículo 27; εἰς κῆπον, «para um jardim», Lc 13:19; lançar sortes (Sl 21:19; 1Cr 25:8 e outros; Josefo, Ant. 6, 61), Mt 27:35; Mc 15:24; Lc 23:34; Jo 19:24; B 6:6. <strong>b. Lançar</strong>, τινί τι, Mt 15:26; Mc 7:27; τὶ ἔμπροσθέν τινος, «lançar algo diante de alguém», Mt 7:6 (lançar diante de animais: Esopo, Fab. 275b H. //158 P.//163 H.); τὶ ἀπό τινος, «lançar algo fora, para longe de alguém», Mt 5:29s.; 18:8s. (Teles, p. 60, 2, ἀποβάλλω, do olho). τὶ ἔκ τινος: ὕδωρ ἐκ τοῦ στόματος ὀπίσω τινός, «expel água da boca atrás de alguém», Ap 12:15s.; β. ἔξω = ἐκβάλλειν, «lançar para fora», Jo 12:31, variante de leitura; 2Cl 7:4; ver ἐκβάλλω 1; do sal imprestável, Mt 5:13; Lc 14:35; dos peixes ruins, «lançar fora», Mt 13:48 (compare Κυπρ. I, p. 44, n.º 43: κόπρια βάλλειν, provavelmente «lançar fora o lixo»). τὶ ἐπί τινα: «atirar pedras contra alguém», Jo 8:7, 59 (compare Sir 22:20; 27:25; Josefo, Vi. 303); numa visão do futuro, lançar poeira sobre a própria cabeça, Ap 18:19; como protesto, τὶ εἴς τι, «lançar pó ao ar», At 22:23 (códice D: εἰς τ. οὐρανόν, «para o céu»); lançar redes ao lago, Mt 4:18; Jo 21:6; compare versículo 7; anzol, Mt 17:27 (compare Is 19:8). Passivo: lançado ao mar ou lago, Mt 13:47; Mc 9:42; βλήθητι εἰς τὴν θάλασσαν, «lança-te ao mar», Mt 21:21; Mc 11:23. — Lançar ao fogo (Josefo, Ant. 10, 95 e 215), Mt 3:10; Mc 9:22; Lc 3:9; Jo 15:6; à Geena, Mt 5:29; 18:9b; 2Cl 5:4; à fornalha, Mt 6:30; 13:42, 50 (compare Dn 3:21); Lc 12:28; 2Cl 8:2; β. ἑαυτὸν κάτω, «lançar-se para baixo», Mt 4:6; Lc 4:9 (compare escólio a Apolônio de Rodes 4, 1212–14a: εἰς τὸν κρημνὸν ἑαυτὸν ἔβαλε; Josefo, Bell. 4, 28). — Ap 8:7s.; 12:4, 9 (escólio a Apolônio de Rodes 4, 57; 28, p. 264, 18: ἐκβληθέντα κατελθεῖν εἰς Ἅιδου, «lançado fora do céu para descer ao Hades»), 13; 14:19; 18:21; 19:20; 20:3, 10, 14s.; lançado numa sepultura, AcPlCor 2:32 (compare τὰ νεκρούμενα καὶ εἰς γῆν βαλλόμενα, Justino, A I, 18, 6). — De enfermidade ou incapacidade física, βεβλημένος, «jazendo» (Josefo, Bell. 1, 629), ἐπὶ κλίνης β., «deitado num leito», Mt 9:2; compare Mc 7:30; lançado ao leito de enfermidade, Ap 2:22. Passivo absoluto (Cônon [século I a.C./I d.C.] 26 Fgm. 1, 17 Jac.: βαλλομένη θνήσκει): «jazer num leito de enfermidade» (compare Bábrio 103, 4: κάμνων ἐβέβλητο [ἔκειτο em L-P.]), Mt 8:6, 14; ἐβέβλητο πρὸς τὸν πυλῶνα, «jazia diante do portão», Lc 16:20 (ἐβέβλητο como Esopo, Fab. 284 H.; Josefo, Ant. 9, 209; Field, Notes 70). — Figurado, εἰς ἀθυμίαν β. τινά, «mergulhar alguém no desânimo», 1Cl 46:9. <strong>c. Fazer cair ou deixar cair:</strong> de árvore que deixa cair frutos, Ap 6:13; «lançar abaixo», 18:21a, para a destruição, no mesmo capítulo, parte b.<br/><strong>2. Lançar alguém para fora de lugar ou para dentro dele: expulsar, afastar, lançar.</strong> ἐβλήθη ἔξω, «é lançado fora» (aoristo que ressalta a certeza do resultado, gnômico; B-D-F §333; Robinson 836s.; ver manual sobre o texto), isto é, expulso da comunhão, Jo 15:6; expulsar para o deserto, B 7:8; lançar na prisão, Mt 18:30; Ap 2:10 (Epicteto 1, 1, 24; 1, 12, 23; 1, 29, 6 e outros; PTebt 567 [53/54 d.C.]); passivo, lançado na cova dos leões, 1Cl 45:6 (compare Dn 6:25, Teodocião, variante; Bel 31, Teodocião, variante); εἰς τὸ στάδιον, «na arena», AcPl Ha 4, 13. Figuradamente, o amor expulsa o medo, 1Jo 4:18.<br/><strong>3. Pôr ou colocar alguma coisa em determinado lugar: colocar, aplicar, depositar, trazer.</strong> <strong>a. Com objeto simples:</strong> κόπρια β., «colocar adubo», Lc 13:8 (POxy 934, 9: μὴ οὖν ἀμελήσῃς τοῦ βαλεῖν τὴν κόπρον). <strong>b. Com indicação do local, τὶ εἴς τι:</strong> colocar dinheiro no tesouro do templo, Mc 12:41–44; Lc 21:1–4 (Mc 12:43s. e Lc 21:3s. sugerem a oferta sacrificial da viúva); τὰ βαλλόμενα, «contribuições» (ver γλωσσόκομον; compare 2Cr 24:10), Jo 12:6; pôr o dedo no ouvido durante uma cura, Mc 7:33; diferentemente Jo 20:25, 27 (exemplos de literatura médica em Rydbeck 158s.); determinar a virgindade mediante exame digital, GJs 19:3; colocar espada na bainha, Jo 18:11; freios na boca de animais, Tg 3:3; εἰς τὴν κολυμβήθραν, «levar à piscina», Jo 5:7; compare Ox 840, 33s.; πολλὰ θηρία εἰς τὸν Παῦλον, «muitos animais soltos contra Paulo», AcPl Ha 5, 4s. (aqui β. sugere o ímpeto dos animais); β. εἰς τὴν καρδίαν, «colocar no coração», Jo 13:2 (compare Odisseia 1, 201; 14, 269; Píndaro, O. 13, 16 [21]: πολλὰ δ’ ἐν καρδίαις ἔβαλον; escólio a Píndaro, P. 4, 133; Plutarco, Timol. 237 [3, 2]; Herm. Wr. 6, 4: θεῷ τῷ εἰς νοῦν μοι βαλόντι). De líquidos: <strong>derramar</strong> (Epicteto 4, 13, 12; PLond III, 1177, 46, p. 182 [113 d.C.]; Jz 6:19, códice B), vinho em odres, Mt 9:17; Lc 5:37s.; água numa bacia (TestAbr B 3, p. 107, 18 [Stone, p. 62]: βάλε ὕδωρ ἐπὶ τῆς λεκάνης ἵνα νίψωμεν τοὺς πόδας τοῦ ξένου; compare TestAbr A 3, p. 80, 1 [Stone, p. 8]: ἔνεγκέ μοι ἐπὶ τῆς λ.; Vi. Aesopi W 61, p. 92, 29s. P.: βάλε ὕδωρ εἰς τ. λεκάνην καὶ νίψον μου τοὺς πόδας; PGM 4, 224; 7, 319: βαλὼν εἰς αὐτὸ ὕδωρ), Jo 13:5; losna no mel, Hm 5, 1, 5; unguento sobre o corpo, Mt 26:12. — βάρος ἐπί τινα, «impor um fardo a alguém», Ap 2:24; δρέπανον ἐπὶ τὴν γῆν, «lançar a foice sobre a terra» como campo de colheita, Ap 14:19; compare ἐπ’ αὐτὸν τὰς χείρας, Jo 7:44, variante de leitura (ver ἐπιβάλλω 1b). Depositar coroas diante do trono, Ap 4:10. <strong>c. Outro uso:</strong> ῥίζας β., «lançar raízes, criar raízes», como árvore, figuradamente (Polemon, Decl. 2, 54: ὦ ῥίζας ἐξ ἀρετῆς βαλλόμενος), 1Cl 39:8 (Jó 5:3).<br/><strong>4. Produzir mudança de estado ou condição:</strong> εἰρήνην, μάχαιραν ἐπὶ τὴν γῆν, «trazer paz, espada à terra», Mt 10:34 (Josefo, Ant. 1, 98: ὀργὴν ἐπὶ τὴν γῆν βαλεῖν); χάριν ἐπ’ αὐτήν, «Deus lhe concedeu favor» (a Maria), GJs 7:3; τὶ ἐνώπιόν τινος, σκάνδαλον, «colocar obstáculo diante de alguém», Ap 2:14.<br/><strong>5. Confiar dinheiro ao banqueiro para obter juros: depositar dinheiro</strong> (τί τινι como em Quinto de Esmirna 12, 250, num contexto diferente); com os banqueiros, para render juros (compare Aristóxeno, Fgm. 59: τὸ βαλλόμενον κέρμα; Diógenes Laércio 2, 20), Mt 25:27.<br/><strong>6. Mover-se repentina e rapidamente para baixo: precipitar-se</strong>, intransitivo (Homero; Epicteto 2, 20, 10; 4, 10, 29; POslo 45, 2; En 18:6: ὄρη … εἰς νότον βάλλοντα, «montanhas que avançam na direção sul»; compare Rdm.² 23; 28s.; Robinson 799; J. Stahl, RhM 66, 1911, 626ss.); ἔβαλεν ἄνεμος, «uma tempestade precipitou-se», At 27:14 (ver Warnecke 36, nota 9). — B. 673; Schmidt, Syn. III, 150–66; DELG; M-M; TW.</p></section></article> <article id=\"entry-banausos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάναυσος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bánausos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(A derivação de βαῦνος ou βαυνός, «forno, forja», pode ser etimologia popular, Frisk; Sófocles, Platão e outros.) <strong>Pertencente à classe dos artesãos, socialmente inferior ou grosseiro nos modos: vulgar, indigno</strong> (essa classe era considerada necessária à existência da cidade [Aristóteles, Pol. 1291a, 1], mas ocupava posição social baixa; daí o sentido transferido «vulgar», Aristóteles, EN 1123a, 19, dos novos ricos, como no grego moderno). οὐδὲν βάναυσον ἐν ἀγάπῃ, «nada há de indigno no amor», 1Cl 49:5 (φορτικὰ καὶ βάναυσα, Justino, D. 3, 3). — DELG; Frisk.</p></section></article> <article id=\"entry-baptizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαπτίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦baptízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro βαπτίσω; primeiro aoristo ἐβάπτισα; médio ἐβαπτισάμην. Passivo: imperfeito ἐβαπτιζόμην; futuro βαπτισθήσομαι; primeiro aoristo ἐβαπτίσθην; particípio perfeito βεβαπτισμένος (Hipócrates, Platão, especialmente Políbio e posteriores; UPZ 70, 13 [152/151 a.C.]; PGM 5, 69; Septuaginta; ApcSed 14:7 [p. 136, 8s. Ja.]; Fílon; Josefo; SibOr 5, 478; Justino; Melitão, Fgm. 8, 1 e 2 Goodsp. = 8b, 4 e 14 P.). Na literatura grega, geralmente significa colocar ou entrar debaixo de água, com vários sentidos, também figurados, como «encharcar-se» de vinho, Platão, Symp. 176b. Na literatura aqui examinada, apenas em sentido ritual ou cerimonial (como em Plutarco; Herm. Wr. [ver acepção 2a]; PGM 4, 44; 7, 441: λουσάμενος κ. βαπτισάμενος; 2Rs 5:14; Sir 34:25; Jt 12:7; compare Irineu 1, 21, 3 [Harv. I, 183, 83]).<br/><strong>1. Lavar cerimonialmente para purificação: lavar, purificar.</strong> De ampla variedade de lavagens rituais repetidas, enraizadas na tradição israelita (compare Justino, D. 46, 2), Mc 7:4; Lc 11:38; Ox 840, 15. — W. Brandt, Jüd. Reinheitslehre u. ihre Beschreibg. in den Ev., 1910; A. Büchler, The Law of Purification in Mk 7:1–23, ET 21, 1910, 34–40; J. Döller, D. Reinheits- u. Speisegesetze d. ATs, 1917; J. Jeremias, TZ 5, 1949, 418–28. Ver 1QS 5:8–23; 2:25–3:12; 4:20–22.<br/><strong>2. Utilizar água num rito para renovar ou estabelecer relação com Deus: imergir, mergulhar, lavar, batizar.</strong> A transliteração «batizar» assinala o caráter cerimonial que as narrativas neotestamentárias atribuem a essa purificação, mas a necessidade de qualificações ou de esclarecimento contextual nos documentos indica que β. não era um termo técnico tão estrito quanto a transliteração sugere.<br/><strong>a. Da purificação dedicatória associada ao ministério de João Batista</strong> (Orígenes, C. Cels. 1, 47, 4): absoluto, Jo 1:25, 28; 3:23a; 10:40; daí João ser chamado ὁ βαπτίζων, «aquele que batiza», Mc 1:4; 6:14, 24 (Goodsp., Probs. 50–52). — Passivo, Mt 3:16; ISm 1:1; frequentemente «fazer-se batizar, receber o batismo», Mt 3:13s.; Lc 3:7, 12, 21; 7:30; Jo 3:23b; GEb 18, 35s.; IEph 18:2 e outros (B-D-F §314; ver §317). — (ἐν) ὕδατι, «com água», Mc 1:8a; Lc 3:16a; At 1:5a; 11:16a; ἐν (τῷ) ὕδατι, Jo 1:26, 31, 33; ἐν τῷ Ἰορδ., «no Jordão» (2Rs 5:14), Mt 3:6; Mc 1:5; εἰς τὸν Ἰορδ., «no Jordão» (compare Plutarco, Mor. 166a: βάπτισον σεαυτὸν εἰς θάλασσαν; Herm. Wr. 4, 4: βάπτισον σεαυτὸν εἰς τὸν κρατῆρα), Mc 1:9. — Com indicação do elemento externo e da finalidade: ἐν ὕδατι εἰς μετάνοιαν, «com água para arrependimento», Mt 3:11a (A. Oliver, Is β. used w. ἐν and the Instrumental?, RevExp 35, 1938, 190–97). — βαπτίζεσθαι τὸ βάπτισμα Ἰωάννου, «submeter-se ao batismo de João», Lc 7:29. εἰς τί ἐβαπτίσθητε;, At 19:3, significa, conforme mostra a resposta, «com referência a qual (batismo) fostes batizados?», isto é, «que espécie de batismo recebestes?». Como indica o contexto, o batismo de João destinava-se a produzir arrependimento, etapa necessária à recepção de Jesus; com a chegada de Jesus, a etapa seguinte era receber o Espírito Santo em conexão com o batismo apostólico em nome de Jesus, que já não era «aquele que viria», mas o «Senhor» que chegara. β. βάπτισμα μετανοίας, «administrar batismo de arrependimento», versículo 4; GEb 13, 74. — Sobre Ἰωάν(ν)ης 1 e o batismo de Jesus por João: J. Bornemann, D. Taufe Christi durch Joh., 1896; H. Usener, D. Weihnachtsfest², 1911; D. Völter, NThT 6, 1917, 53–76; W. Bundy, JR 7, 1927, 56–75; M. Jacobus, NKZ 40, 1929, 44–53; S. Hirsch, Taufe, Versuchung u. Verklärung Jesu, 1932; D. Plooij, R. Harris Festschrift, Amicitiae Corolla, org. H. Wood, 1933, 239–52; J. Kosnetter, D. Taufe Jesu, 1936; H. Rowley, memorial T. Manson, org. Higgins, 1959, 218–29, sobre Qumran; J. Schneider, Der historische Jesus u. d. kerygmatische Christus, 1961, 530–42; H. Kraft, TZ 17, 1961, 399–412, sobre Joel; F. Lentzen-Dies, D. Taufe Jesu nach den Synoptikern, 1970. Outras referências em περιστερά.<br/><strong>b. Da purificação efetuada por Jesus</strong>, Jo 3:22, 26; 4:1; diferentemente Jo 4:2, com a ressalva de que Jesus pessoalmente não realizava os batismos.<br/><strong>c. Do sacramento cristão de iniciação depois da morte de Jesus</strong> (frequentemente no passivo, ver acima 2a; Irineu 3, 12, 9 [Harv. II, 63, 3]), Mc 16:16; At 2:41; 8:12s., 36, 38; 9:18; 10:47; 16:15, 33; 18:8; 22:16; 1Co 1:14–17; D 7 (onde se admite batismo por derramamento em casos de necessidade); ISm 8:2. — β. τινὰ εἰς (τὸ) ὄνομά τινος (ver ὄνομα 1dγβ), «batizar no nome ou com referência ao nome de alguém»: (τοῦ) κυρίου, «do Senhor», At 8:16; 19:5; D 9:5; Hv 3, 7, 3; compare 1Co 1:13, 15. εἰς τ. ὄν. τ. πατρὸς καὶ τ. υἱοῦ καὶ τ. ἁγίου πνεύματος, «em nome do Pai e do Filho e do Espírito Santo», Mt 28:19 (sobre a forma original da fórmula batismal, ver F. Conybeare, ZNW 2, 1901, 275–88; E. Riggenbach, BFCT VII/1, 1903; VIII/4, 1904; H. Holtzmann, Ntl. Theologie² I, 1911, 449s.; O. Moe, em R. Seeberg Festschrift, 1929, I, 179–96; G. Ongaro, Biblica 19, 1938, 267–79; G. Braumann, Vorpaulinische christl. Taufverkündigung bei Paulus, 1962); D 7:1, 4. Da mesma forma, ἐν τῷ ὀν. Ἰ. Χριστοῦ, «em nome de Jesus Cristo», At 2:38, variante de leitura; 10:48; ἐπὶ τῷ ὀν. Ἰ. Χρ., At 2:38, texto principal; mais brevemente εἰς Χριστόν, «em Cristo», Gl 3:27; Rm 6:3a. Ser batizado εἰς Χρ. representa, para Paulo, participação na morte de Cristo e em suas implicações para o crente: εἰς τὸν θάνατον αὐτοῦ ἐβαπτίσθημεν, «fomos batizados em sua morte», versículo 3b (ver Lietzmann, comentário; H. Schlier, EvTh 1938, 335–47; G. Wagner, D. relgeschichtliche Problem von Rö 6:1–11, 1962, tradução Pauline Baptism and the Pagan Mysteries, por J. Smith, 1967; R. Schnackenburg, Baptism in the Thought of St. Paul, 1964, tradução de D. Heilsgeschehen b. d. Taufe nach dem Ap. Paulus, 1950). O efeito do batismo é inserir todos os batizados εἰς ἓν σῶμα, «num só corpo», 1Co 12:13 (talvez com jogo de palavras: «mergulhados num só corpo»). — Com finalidade expressa, εἰς ἄφεσιν τ. ἁμαρτιῶν, «para remissão dos pecados», At 2:38 (I. Scheftelowitz, D. Sündentilgung durch Wasser, ARW 17, 1914, 353–412). — Diodoro Sículo 5, 49, 6: muitos creem que, ao serem recebidos nos mistérios por meio dos ritos (τελεταί), tornam-se mais devotos, mais justos e melhores em todos os aspectos. — ὑπὲρ τ. νεκρῶν, «pelos mortos», 1Co 15:29a, ver também versículo 29b, é obscuro devido ao conhecimento limitado de uma prática aparentemente conhecida dos destinatários de Paulo. Tem sido interpretado como (1) «em lugar dos mortos», isto é, vicariamente; (2) «em benefício dos mortos», em sentidos variados; (3) localmente, «sobre [os túmulos] dos mortos»; (4) «por causa dos mortos», sob a influência do bom exemplo deles. Destas, as duas últimas são as menos prováveis. Ver comentários e H. Preisker, ZNW 23, 1924, 298–304; J. Zingerle, Heiliges Recht, JÖAI 23, 1926; Reitzenstein, Taufe 43s.; A. Marmorstein, ZNW 30, 1931, 277–85; A. Oliver, RevExp 34, 1937, 48–53; três artigos em Kirchenblatt 98, 1942, e seis em ET 54, 1943; 55, 1944; M. Raeder, ZNW 46, 1956, 258–60; B. Foschini, cinco artigos em CBQ 12, 1950, e 13, 1951. — Sobre substituição de um rito por outra pessoa, compare Diodoro Sículo 4, 24, 5: rapazes que não realizam os sacrifícios habituais perdem a voz e tornam-se como mortos no recinto sagrado; quando alguém assume o voto de fazer o sacrifício por eles, o problema desaparece imediatamente.<br/><strong>3. Fazer alguém passar por experiência extraordinária semelhante a rito iniciático com água: mergulhar, batizar.</strong> Compare a expressão «dar o mergulho» e OED, «Plunge» II 5, sobretudo para a acepção 3c abaixo. <strong>a. Tipologicamente, da passagem de Israel pelo mar Vermelho:</strong> εἰς τὸν Μωϋσῆν ἐβαπτίσαντο, «foram mergulhados/batizados com referência a Moisés», afirmando assim sua liderança, 1Co 10:2, variante de leitura (se o passivo ἐβαπτίσθησαν for adotado com N., a ideia permanece, mas a forma média, conforme o contexto, atribui a responsabilidade aos próprios israelitas). <strong>b. Do Espírito Santo (e fogo):</strong> β. τινὰ (ἐν) πνεύματι ἁγίῳ, «batizar alguém com/no Espírito Santo», Mc 1:8 (variante acrescenta ἐν); Jo 1:33; At 1:5b; 11:16b; compare 1Co 12:13 (e Justino, D. 29, 1). ἐν πν. ἁγ. καὶ πυρί, «com o Espírito Santo e fogo», Mt 3:11b; Lc 3:16b (J. Dunn, NovT 14, 1972, 81–92). Sobre o oxímoro do batismo com fogo: R. Eisler, Orphischdionysische Mysterienged. in d. christl. Antike, Vortr. d. Bibl. Warburg II/2, 1925, 139ss.; C. Edsman, Le baptême de feu, ASNU 9, 1940; J. A. T. Robinson, The Baptism of John and Qumran, HTR 50, 1957, 175–91; compare 1QS 4:20s. <strong>c. Do martírio</strong> (ver usos figurados em UPZ 70, 13 [152/151 a.C.]; Diodoro Sículo 1, 73, 6; Plutarco, Galba 1062 [21, 3]: ὀφλήμασι βεβ., «sobrecarregado de dívidas»; Cáriton 2, 4, 4: βαπτιζόμενος ὑπὸ τ. ἐπιθυμίας; Vi. Aesopi I, capítulo 21, p. 278, 4: λύπῃ βαπτιζόμενος; Aquiles Tácio 3, 10, 1: πλήθει βαπτισθῆναι κακῶν; Herm. Wr. 4, 4: ἐβαπτίσαντο τοῦ νοός; Is 21:4; Josefo, Bell. 4, 137: ἐβάπτισεν τ. πόλιν, «afogou a cidade em desgraça»): δύνασθε τὸ βάπτισμα ὃ ἐγὼ βαπτίζομαι βαπτισθῆναι;, «podeis receber o batismo com que eu sou batizado?», Mc 10:38 (talvez a metáfora contundente da iminente catástrofe pessoal devesse ser traduzida «estais preparados para afogar-vos como serei afogado?»); compare versículo 39; Mt 20:22, variante de leitura; em forte contraste com fogo, Lc 12:50 (G. Delling, NovT 2, 1957, 92–115).<br/>Bibliografia adicional: P. Althaus, Senior, D. Heilsbedeutung d. Taufe im NT, 1897; W. Heitmüller, Im Namen Jesu, 1903; Taufe u. Abendmahl b. Paulus, 1903; Taufe u. Abendmahl im Urchristentum, 1911; F. Rendtorff, D. Taufe im Urchristentum, 1905; H. Windisch, Taufe u. Sünde im ältesten Christentum, 1908; A. Seeberg, D. Taufe im NT², 1913; A. v. Stromberg, Studien zu Theorie u. Praxis der Taufe, 1913; Gottfr. Kittel, D. Wirkungen d. chr. Wassertaufe nach d. NT, StKr 87, 1914, 25ss.; W. Koch, D. Taufe im NT³, 1921; J. Leipoldt, D. urchr. Taufe im Lichte der Relgesch., 1928; R. Reitzenstein, D. Vorgesch. d. christl. Taufe, 1929 (contra, H. Schaeder, Gnomon 5, 1929, 353–70, respondido por Reitzenstein, ARW 27, 1929, 241–77); F. Dölger, Ac I, 1929, II, 1930; H. v. Soden, Sakrament u. Ethik bei Pls, em R. Otto Festschrift, Marburger Theologische Studien, 1931, n.º 1, 1–40; M. Enslin, Crozer Quarterly 8, 1931, 47–67; B. Bacon, ATR 13, 1931, 155–74; C. Bowen, em R. Hutcheon, Studies in NT, 1936, 30–48; G. Bornkamm, ThBl 17, 1938, 42–52; 18, 1939, 233–42; H. Schlier, EvTh 1938, 335–47 (Rm 6); E. Bruston, La notion bibl. du baptême, ÉTLR 1938, 67–93; 135–50; H. Marsh, The Origin and Signif. of the NT Baptism, 1941; K. Barth, D. kirchl. Lehre v. d. Taufe², 1943 (tradução The Teaching of the Church Regarding Baptism, E. Payne, 1948); F. Grant, ATR 27, 1945, 253–63; H. Schlier, TLZ 72, 1947, 321–26; O. Cullmann, Baptism in the NT, tradução J. Reid, 1950; M. Barth, D. Taufe ein Sakrament?, 1951; R. Bultmann, Theology of the NT, tradução K. Grobel, 1951, I, 133–44; J. Schneider, D. Taufe im NT, 1952; D. Stanley, TS 18, 1957, 169–215; E. Fascher, Taufe, Pauly-W., segunda série IV, 2501–18, 1932; A. Oepke, TW I, 1933, 527–44; G. Beasley-Murray, Baptism in the NT, 1962; M. Quesnel, Baptisés dans l’Esprit, 1985 (Atos); D. Daube, The NT and Rabbinic Judaism, 1956, 106–40; N. McEleney, Conversion, Circumstance and the Law, NTS 20, 1974, 319–41; H. Braun, Qumran u. d. NT II, 1966, 1–29; O. Betz, D. Proselytentaufe der Qumransekte u. d. NT, RevQ 1, 1958, 213–34; J. Ysebaert, Greek Baptismal Terminology, 1962. Ver τέκνον 1aα. — B. 1482; DELG, s.v. βάπτω; M-M; EDNT; TW; Sv.</p></section></article> <article id=\"entry-baptisma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάπτισμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦báptisma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βαπτίζω; encontrado somente em escritores cristãos; ApcSed 14:6 [p. 136, 7 e 9 Ja.]; Justino, D.; Melitão, Fgm. 6 e outros.)<br/><strong>1. Uso cerimonial da água com a finalidade de renovar ou estabelecer relação com Deus: imersão, mergulho, lavagem, rito com água, batismo.</strong> <strong>a. Do rito de João</strong> (Orígenes, C. Cels. 1, 44, 13 e outros, no Testamento de Jesus), Mt 3:7; 21:25; Mc 11:30; Lc 7:29; 20:4; At 1:22; 10:37; 18:25; 19:3. β. μετανοίας, «batismo de arrependimento», Mc 1:4; Lc 3:3 (nessas duas passagens com εἰς ἄφεσιν ἁμαρτιῶν, «[proclamar] um batismo acompanhado de arrependimento para receber perdão dos pecados»); At 13:24; 19:4; GEb 13, 74. <strong>b. Do rito cristão</strong>: β. φέρον ἄφεσιν ἁμαρτιῶν, «batismo que traz remissão dos pecados», B 11:1; β. εἰς τὸν θάνατον, «batismo para a morte», Rm 6:4 (ver βαπτίζω 2b); ἓν β., «um só batismo», Ef 4:5. A pessoa batizada é simultaneamente sepultada com Cristo, Cl 2:12, variante de leitura; 1Pe 3:21 (ver ἀντίτυπος). Comparado às armas de um soldado, IPol 6:2; τηρεῖν τὸ β. ἁγνὸν καὶ ἀμίαντον, «manter o batismo puro e imaculado», 2Cl 6:9. Instruções rituais em D 7:1, 4.<br/><strong>2. Experiência extraordinária semelhante a um rito iniciático de purificação: mergulho, batismo.</strong> <strong>a. Metaforicamente, do martírio</strong>, Mc 10:38s.; Lc 12:50; Mt 20:22s., variante de leitura (ver G. Delling, NovT 2, 1958, 92–115, e βαπτίζω 3c). <strong>b. Metaforicamente, da salvação</strong>: β. ἐν σωτηρίᾳ Ἀχερουσίας λίμνης, «batismo nas águas salvíficas do lago Aquerúsio», ApcPt Rainer 1, 4s. (ver Ἀχερούσιος; E. Peterson, Frühkirche, Judentum u. Gnosis, 1959, 310ss.). — M-M; TW.</p></section></article> <article id=\"entry-baptismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαπτισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦baptismós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βαπτίζω; Antilo, médico [século II d.C.], em Oribásio 10, 3, 9, «ato de imergir ou mergulhar».)<br/><strong>1. Rito com água para purificação: lavagem, limpeza</strong>, de recipientes, Mc 7:4, 8, variante de leitura; de outras lavagens rituais (Josefo, Ant. 18, 117, do batismo de João), Hb 9:10. — E. Sanders, Jewish Law from Jesus to the Mishnah, 1990, 258–71, sobre purificação.<br/><strong>2. Rito com água para renovar ou estabelecer relação com Deus: experiência de imersão, batismo.</strong> Sepultamento com Cristo no batismo, Cl 2:12; βαπτισμῶν διδαχή, «doutrina de batismos», Hb 6:2 (referência a vários ritos com água, incluindo provavelmente o batismo de João e o batismo cristão). — M-M; TW.</p></section></article>"};
